mapper.select:
/*selectSellerMpClPositionCodePop*/

		SELECT
		    CODE
		  , TEXT1
		  , TEXT2
		FROM
		    ICOMCOD2 /* 회사별 코드관리 */
		WHERE 1=1
		AND TYPE = #{st_type}
		AND CODE = #{st_code}
		AND COMPANY_CODE = #{st_com_code}

/*selectSellerMpClPositionCodePop_Count*/

		SELECT
		    COUNT(*) AS CNT 
		FROM
		    ICOMCOD2 /* 회사별 코드관리 */
		WHERE 1=1
		AND TYPE = #{st_type}
		AND CODE = #{st_code}
		AND COMPANY_CODE = #{st_com_code}

mapper.update:
/*insertSellerMpClPositionCodePop*/

		INSERT INTO ICOMCOD2 /* 회사별 코드관리 */
		(
		    TYPE
		  , CODE 
		  , COMPANY_CODE 
		  , TEXT1 
		  , TEXT2
		  , FLAG 
		  , ADD_DATE 
		)
		VALUES
		(
		    #{st_type}
		  , #{st_code}
		  , #{st_com_code}
		  , #{st_text1}
		  , #{st_text2}
		  , 'Y'
		  , TO_CHAR(SYSDATE, 'YYYYMMDD')
		)

/*updateSellerMpClPositionCodePop*/

		UPDATE 
		    ICOMCOD2 /* 회사별 코드관리 */
		SET TEXT1 = #{st_text1}
		  , TEXT2 = #{st_text2}
		WHERE 1=1
		AND TYPE  = #{st_type}
		AND CODE  = #{st_code}
		AND COMPANY_CODE = #{st_com_code}

/*"deleteSellerMpClPositionCodePop"*/

		DELETE 
		    ICOMCOD2 /* 회사별 코드관리 */
		WHERE 1=1
		AND TYPE  = #{st_type}
		AND CODE  = #{st_code}
		AND COMPANY_CODE = #{st_com_code}
